# The reproducible-figures contract (REPRODUCE.md): every asset the paper and
# the supplement read is indexed, generated by an existing script that writes
# it or declared static with provenance, every generated asset names its config
# of record (configs/figures/*.toml) and its generator reads it, and no
# generated number is re-typed in the prose. The check is VisualGeometryEval's
# `Reproduce`.
using Test
using DrWatson: projectdir
import VisualGeometryEval

# VisualGeometryEval releases from the one that ships `Reproduce` on carry it;
# an older resolved version reads the dependency-free implementation file from
# a checkout that has it (VGEVAL_REPRODUCE_SRC = .../src/reproduce/reproduce_index.jl).
const Reproduce = if isdefined(VisualGeometryEval, :Reproduce)
    VisualGeometryEval.Reproduce
else
    let src = get(ENV, "VGEVAL_REPRODUCE_SRC", "")
        isfile(src) || error(
            "VisualGeometryEval $(pkgversion(VisualGeometryEval)) predates Reproduce: update it, or set " *
                "VGEVAL_REPRODUCE_SRC to src/reproduce/reproduce_index.jl of a checkout that has it"
        )
        m = Module(:Reproduce)
        Base.include(m, src)
        m
    end
end

const PAPERS = ["papers/blob_boards_bmvc.tex", "papers/bmvc_supp.tex"]

@testset "bmvc2026 reproducible figures (REPRODUCE.md)" begin
    vs = Reproduce.reproduce_index_violations(projectdir(); papers = PAPERS, require_config = true)
    foreach(v -> @info(sprint(show, v)), vs)
    @test isempty(vs)
    # The index covers what the documents read — not vacuously.
    graph = Reproduce.paper_asset_graph(projectdir.(PAPERS); root = projectdir())
    @test length(graph.assets) > 100
    @test all(a -> a.exists, graph.assets)
end

# Every figure config of record is a TOML whose [experiment] names a generator
# that exists and reads it, and that generator holds no `const` data tables:
# the picks, crops, seeds and panel lists live in the config.
@testset "bmvc2026 figure configs of record" begin
    import TOML
    dir = projectdir("configs", "figures")
    scripts = Dict(
        "supp_tables" => ["make_supp_tables.jl"], "val_overlays" => ["copy_val_overlays.jl"],
        "occlusion_picks" => ["make_occlusion_picks.jl"], "param_variations" => ["make_param_variations.jl"],
        "adapted_panels" => ["make_adapted_panels.jl"], "intro" => ["make_bmvc2026_intro.jl"],
        "pipeline_panels" => ["make_pipeline_panels.jl"], "regenerate_paper" => ["regenerate_paper.jl"],
        "evaluation" => ["plots/error_distributions.jl", "flip_table.jl", "make_detection_stats.jl", "make_hand_eye_table.jl"],
    )
    for f in filter(endswith(".toml"), readdir(dir))
        gen = TOML.parsefile(joinpath(dir, f))["experiment"]["generator"]
        @test f == gen * ".toml"
        for script in scripts[gen]
            src = read(projectdir("scripts", script), String)
            @test occursin("figure_config(\"$(gen)\"", src)
            @test occursin("reproduce: reads configs/figures/$(f)", src)
            @test occursin("@quickactivate", src)
            @test occursin("write_figure_records", src)
            # no data tables in a figure generator: `const NAME = [` / `= Dict(` / `= (`
            # literals (the evaluation drivers' structural tables — system order,
            # display names, colours — are PaperProjects C2's to judge)
            gen == "evaluation" || @test !occursin(r"^const [A-Z_]+ = (\[|Dict\(|\()"m, src)
        end
    end
    @test Set(keys(scripts)) == Set(first.(splitext.(filter(endswith(".toml"), readdir(dir)))))
end

# Every figure generator that runs detection takes its detector, adaptation,
# matching and verification settings from the evaluation's run config of
# record (`[inputs] run_config`, read by reference, no detector values
# restated) unless its config declares a reasoned `[find_boards]
# detector_exception` — so a figure and the evaluation cannot silently diverge.
@testset "bmvc2026 figures use the run config of record" begin
    import TOML
    detector_keys = ("peak_threshold", "edge_threshold", "nms_cutoff", "nms_band_octaves", "upsample", "tilts")
    has_key(d, k) = d isa AbstractDict && (haskey(d, k) || any(v -> has_key(v, k), values(d)))
    for f in filter(endswith(".toml"), readdir(projectdir("configs", "figures")))
        cfg = TOML.parsefile(projectdir("configs", "figures", f))
        gen = cfg["experiment"]["generator"]
        script = Dict("adapted_panels" => "make_adapted_panels.jl", "intro" => "make_bmvc2026_intro.jl",
            "pipeline_panels" => "make_pipeline_panels.jl")
        haskey(script, gen) || continue
        src = read(projectdir("scripts", script[gen]), String)
        occursin(r"\b(find_boards|trace_pipeline|detect_blobs)\(", src) || continue
        exception = get(get(cfg, "find_boards", Dict()), "detector_exception", "")
        if isempty(exception)
            run = get(get(cfg, "inputs", Dict()), "run_config", "")
            @test !isempty(run) && isfile(projectdir("configs", run))
            @test occursin("FindBoardsConfig(CONFIG_PATH", src)
            @test !any(k -> has_key(cfg, k), detector_keys)      # no restated detector values
        else
            @test length(exception) > 20                          # a reason, not a flag
        end
    end
    # every generator that runs detection is covered by the table above
    for f in readdir(projectdir("scripts"))
        endswith(f, ".jl") && startswith(f, "make_") || continue
        src = read(projectdir("scripts", f), String)
        occursin("reproduce: writes papers/images", src) || continue
        occursin(r"\b(find_boards|trace_pipeline)\(", src) || continue
        @test f in ("make_adapted_panels.jl", "make_bmvc2026_intro.jl", "make_pipeline_panels.jl")
    end
end

